nativeSource:
{
  --lini-font-family: Arial;
  .lini-block { font-family: Arial; }
  .lini-caption { translate: 0 -30; font-scale: 14 16; }
  .e1 { stroke: --teal-deep; }
  .e2 { stroke: --teal-deep; }
  .e3 { stroke: --teal-deep; }
}
|group#visual| "V6 · Commit is not query visibility" { layout: grid; columns: repeat(2); gap: 72; padding: 36; fill: none; stroke: none; stroke-width: 0; } [
  |box#n1| "Write transaction · commit" { width: 240; } [
    |cell#detail| "Business change + terminal outcome +\noutbox fact commit together. Receipt\ncarries store, epoch and opaque\nversion."
  ]
  |box#n2| "Delivery · position 2\narrives first" { width: 240; } [
    |cell#detail| "Position 1 is missing. Complete\napplied prefix stays 0. A larger\nreceived position proves no\nvisibility."
  ]
  |box#n3| "Projection · position 1 then\n2" { width: 240; } [
    |cell#detail| "Apply exact facts in order. Update\nread content and contiguous prefix\natomically. Repeated delivery is\ndeduplicated."
  ]
  |box#n4| "Read at least the receipt" { width: 240; } [
    |cell#detail| "Check current reader authorization\nfirst: denied readers receive no\ncontent. A receipt grants no access.\nAuthorized freshness is visible only\nfor the matching store/epoch and\nqualified content through the complete\nprefix; otherwise pending or\nunsupported."
  ]
  |box#n5| "Restore boundary" { width: 240; } [
    |cell#detail| "Rotate visibility epoch and fence\nuncertain restored state. Epoch\nrotation does not erase old replay\nidentity or authorize retry."
  ]
  n1 -> n2 "Delivery can arrive out of order" .e1 { along: 0.35; }
  n2 -> n3 "Apply the complete prefix" .e2 { along: 0.5; }
  n3 -> n4 "Check reader authorization and freshness" .e3 { along: 0.65; }
]
